/// <summary>
/// CB166_SalesOrderSubstitutes
/// Main class to process sales order line substitution
/// </summary>
abstract class METSubstitutionSalesLineProcess
{
    SalesLine               salesLine;
    SalesTable              salesTable;
    METSalesItemSubstitute  salesItemSubstitute;
    boolean                 validate;
    CustParameters          custParameters;
    boolean                 updateSalesOrderProcessingStatus;

    //CB238 - xDock order processing
    boolean isCrossDockOrder;

}

Method.Source:
    /// <summary>
    /// Public construct method to search substitute record
    /// </summary>
    /// <param name = "_salesLine">Sales order line to substitute</param>
    /// <param name = "_validate">Validate</param>
    /// <param name = "_updateSalesOrderProcessingStatus">Update sales order header processing status</param>
    /// <returns>Instance of <c>METSubstitutionSalesLineProcess</c></returns>
    public static METSubstitutionSalesLineProcess construct(SalesLine _salesLine, boolean _validate = true, boolean _updateSalesOrderProcessingStatus = true, boolean _xDockProcess = false)
    {
        METSalesItemSubstituteSearch    salesItemSubstituteSearch;
        METSalesItemSubstitute          salesItemSubstitute;

        METSalesItemSubstitutionEnabled custSubstituteEnabled = CustTable::find(_salesLine.CustAccount).METSalesItemSubstitutionEnabled;
        
        salesItemSubstituteSearch = METSalesItemSubstituteSearch::construct(_salesLine, custSubstituteEnabled, _xDockProcess);

        salesItemSubstitute = salesItemSubstituteSearch.search();

        return METSubstitutionSalesLineProcess::constructFromSubstituteSearch(_salesLine, custSubstituteEnabled, salesItemSubstitute, _validate, _updateSalesOrderProcessingStatus, _xDockProcess);
    }

    /// <summary>
    /// Construct method after running the substitute search
    /// </summary>
    /// <param name = "_salesLine">Sales order line to substitute</param>
    /// <param name = "_custSubstituteEnabled">Customer substitutions enabled</param>
    /// <param name = "_salesItemSubstitute">Found <c>METSalesItemSubstitute</c> substitute record</param>
    /// <param name = "_validate">Validate</param>
    /// <param name = "_updateSalesOrderProcessingStatus">Update sales order header processing status</param>
    /// <returns>Instance of <c>METSubstitutionSalesLineProcess</c></returns>
    protected static METSubstitutionSalesLineProcess constructFromSubstituteSearch(SalesLine _salesLine, METSalesItemSubstitutionEnabled _custSubstituteEnabled, METSalesItemSubstitute _salesItemSubstitute, boolean _validate = true, boolean _updateSalesOrderProcessingStatus = true, boolean _xDockOrder = false)
    {
        METSubstitutionSalesLineProcess ret;
        
        
        if (_salesItemSubstitute)
        {
            // if customer substitute enabled and substitution code is not never
            if (_custSubstituteEnabled && _salesItemSubstitute.SubstitutionCode != METSalesItemSubstitutionCode::Never)
            {
                ret = new METSubstitutionSalesLineProcess_Enabled(_salesLine, _salesItemSubstitute, _validate, _updateSalesOrderProcessingStatus, _xDockOrder);
            }
            else
            {
                // Never is treated as disabled as logic dependent on previous substitution or not
                ret = new METSubstitutionSalesLineProcess_Disabled(_salesLine, _salesItemSubstitute, _validate, _updateSalesOrderProcessingStatus, _xDockOrder);
            }
        }
        else
        {
            // When no substitute found, METSubstitutionSalesLineProcess_None will not do anything
            ret = new METSubstitutionSalesLineProcess_None(_salesLine, _salesItemSubstitute, _validate, _updateSalesOrderProcessingStatus, _xDockOrder);
        }

        return ret;
    }

    /// <summary>
    /// New method
    /// </summary>
    /// <param name = "_salesLine">Sales order line</param>
    /// <param name = "_salesItemSubstitute"><c>METSalesItemSubstitute</c> record</param>
    /// <param name = "_validate">Validate</param>
    /// <param name = "_updateSalesOrderProcessingStatus">Update sales order header processing status</param>
    protected void new(SalesLine               _salesLine, 
                       METSalesItemSubstitute  _salesItemSubstitute,
                       boolean                 _validate,
                       boolean                 _updateSalesOrderProcessingStatus,
                       boolean                 _xDockOrder = false)
    {
        salesLine   = _salesLine;
        salesTable  = salesLine.salesTable();
        salesItemSubstitute = _salesItemSubstitute;
        validate = _validate;
        updateSalesOrderProcessingStatus = _updateSalesOrderProcessingStatus;
        
        //CB238 - xDock order processing
        isCrossDockOrder = _xDockOrder;

        custParameters = CustParameters::find();
        
    }

    /// <summary>
    /// Validate, execute substitution and update sales order header processing status
    /// </summary>
    /// <returns>True if substitution; otherwise, false.</returns>
    public boolean run()
    {
        boolean ret = false;
        boolean substitute = true;        
        
        if (validate)
        {
            // validate we can substitute the SO line
            substitute = this.validateSubs();
        }

        if (substitute)
        {
            setPrefix(strFmt("@MET:SalesLineInventTransIdItemNumberPrefix", salesLine.SalesId, salesLine.InventTransId, salesLine.ItemId));
            
            // execute substitution
            ret = this.substitute();

            if (ret && updateSalesOrderProcessingStatus)
            {
                this.updateSalesOrderProcessingStatus();
            }
        }

        return ret;
    }

    /// <summary>
    /// For the Substitutions disabled AND a previous substitution has not been applied to the line with Substitution type blank scenario
    /// </summary>
    /// <param name = "_salesLine">Sales order line</param>
    protected void noPreviousSubUpdateExistingLine(SalesLine _salesLine)
    {
        // if no previous substituion
        // Update current SalesLine
        ttsbegin;
        METSalesLine metSalesLine = METSalesLine::find(_salesLine.RecId, true);

        if (metSalesLine)
        {
            metSalesLine.SubstituteItemID = salesItemSubstitute.SubstituteItemId;
            metSalesLine.SubstitutionType = METSalesItemSubstitutionType::AlternateSuggestion;
            metSalesLine.SubstitutionCode = salesItemSubstitute.SubstitutionCode;

            if (!metSalesLine.ReasonId)
            {
                metSalesLine.ReasonId = this.setReasonCode();
            }

            // Updates subs recId
            metSalesLine.SubstitutionSetupRefRecID = salesItemSubstitute.RecId;

            metSalesLine.update();
        }

        // cancel salesLine
        SalesLine salesLineUpd = SalesLine::findRecId(_salesLine.RecId, true);
        salesLineUpd.metCancelSalesOrderLine();

        ttscommit;
    }

    /// <summary>
    /// Cancel existing order line and create a new one by copying most of the values from the original line, excluding price.
    /// </summary>
    /// <param name = "_salesLine">Existing order line</param>
    /// <returns>New order line</returns>
    protected SalesLine cancelAndCopyToNewLine(SalesLine _salesLine)
    {
        SalesLine       salesLineNew, existingLine = _salesLine;
        METSalesLine    metSalesLineNew, metSalesLine = existingLine.metSalesLine();
        //SalesTable      salesTable      = existingLine.salesTable();
        
        ttsbegin;
        
        // copy metSalesLine into metSalesLineNew before cancelling existingLine
        buf2Buf(metSalesLine, metSalesLineNew);

        // cancel current sales line
        existingLine.metCancelSalesOrderLine();            
        // get current line custom fields
        metSalesLine = METSalesLine::find(existingLine.RecId, true);
        // update current line reason code
        metSalesLine.ReasonId = custParameters.METDefaultCancellationReasonCode;
        metSalesLine.update();

        // create a new salesLine        
        metSalesLineNew.salesLine = 0;

        salesLineNew.initFromSalesTable(salesTable);
        salesLineNew.initFromSalesLine(existingLine, true, true, true);
        //salesLineNew.ItemId             = this.setItemId(metSalesLine);
        salesLineNew.ItemId = this.setItemId(metSalesLine.SubstitutionType, metSalesLine.SubstituteOriginalItemID);
        salesLineNew.PackedExtensions   = conNull();
        
        // Moved before salesLineNew.itemIdChanged() to set the sell UOM so that it doesn't look for the wrong unit conversion which may not exist
        InventItemSalesSetup salesSetup;
        [salesSetup, salesLineNew.SalesUnit] = InventItemSalesSetup::METGetSalesUnit(salesLineNew.ItemId, salesLineNew.InventDimId);

        salesLineNew.itemIdChanged();        

        // QTY convert from old UOM to NEW UOM
        salesLineNew.SalesQty = this.calculateSubstituteQty(existingLine.ItemId,
                                                            salesLineNew.itemId,
                                                            salesLineNew.InventDimId,
                                                            existingLine.SalesUnit,
                                                            salesLineNew.SalesUnit,
                                                            existingLine.SalesQty,
                                                            salesSetup);

        // Need to do something here for inventQty recalc and inventTrans
        salesLineNew.METSkipQuantityUpdatePrompts = true;
        SalesLine::modifySalesQty(salesLineNew,
                                  salesLineNew.inventDim(),
                                  false,
                                  false);
        salesLineNew.METSkipQuantityUpdatePrompts = false;
        
        // Set custom fields
        this.setNewMetSalesLine(metSalesLineNew, metSalesLine);

        // this will save and create metSalesLineNew
        salesLineNew.metPackMETSalesLine(metSalesLineNew);
        
        salesLineNew.LineAmount = 0;
        salesLineNew.PriceUnit = 0;

        // this will insert the new sales line
        salesLineNew.createLine(true, false, false, false, false);

        if (this.cancelNewLine())
        {
            // cancel newSalesLine only if customer substitutions disabled
            salesLineNew.metCancelSalesOrderLine();
        }

        //metSalesLine    = metSalesLineNew
        if(isCrossDockOrder && salesLineNew)
        {
            this.updateTransferOrders(existingLine, salesLineNew);
        }

        ttscommit;

        return salesLineNew;
    }

    private void updateTransferOrders(SalesLine _origSalesLine, SalesLine _newSalesLine)
    {
        METInventTransferLine metTransferLine;
        InventTransferLine transferLine;
        InventTransferId transferId;

        select firstonly metTransferLine
            where metTransferLine.SalesLineTransId == _origSalesLine.InventTransId
            join transferLine
            where transferLine.RecId == metTransferLine.InventTransferLine;
        
        transferId = transferLine.TransferId;

        if(metTransferLine)
        {
            delete_from transferLine 
                where transferLine.RecId == metTransferLine.InventTransferLine;

            metTransferLine.selectForUpdate(true);
            metTransferLine.delete();
        }

        METCrossDockTransferOrderProcessor::construct().CreateTransferOrder(_newSalesLine.salesTable(), _newSalesLine.RecId);
    }

    /// <summary>
    /// Validate substitution before executing it
    /// </summary>
    /// <returns>True if validation successful; otherwise, false</returns>
    protected boolean validateSubs()
    {
        boolean ret = true;

        // Step 2.1: Check the lines are to be included / excluded
        // Exit the substitution process for this sales line (skip the steps 2.2 -2.6), and attempt to process substitution for the next sales line if:
        // The line has any reservation at all (even if it is partial and not for the full quantity)
        if (salesLine.mcrSalesQtyReserved())
        {
            ret = checkFailed("@MET:ValidateQtyReserved");
        }

        // Exit the substitution process for this sales line (skip the steps 2.2 -2.6), and attempt to process substitution for the next sales line if:
        // The line is cancelled,
        if (salesLine.SalesStatus == SalesStatus::Canceled)
        {
            ret = checkFailed("@MET:ValidateCanceledStatus");
        }

        // Step 1: Check substitution applies for the order’s Metcash Sales Order Type
        // Confirm the “Metcash sales order type” allows for substitution.
        if (!METSalesOrderTypes::find(salesTable.METSalesOrderType).SubstitutesAllowed)
        {
            ret = checkFailed(strFmt("@MET:ValidateSubstitutesAllowed", salesTable.SalesId, salesTable.METSalesOrderType));
        }

        return ret;
    }

/// <summary>
/// Main substitute method defined in child class
/// </summary>
/// <returns>True if there was a substitution; otherwise, false.</returns>
abstract protected boolean substitute()
{

}

/// <summary>
/// Set reason code when there was no previous substitute (e.g. parent/child from IOM) or for a new sales order line
/// </summary>
/// <returns>Reason code</returns>
abstract protected ReasonCode setReasonCode()
{
    
}

/// <summary>
/// Set substitution type for the new line
/// </summary>
/// <returns>Substitution type</returns>
abstract protected METSalesItemSubstitutionType setSubstitutionType()
{
    
}

/// <summary>
/// Set item number for the new line
/// </summary>
/// <param name = "_substitutionType">Substitution type</param>
/// <param name = "_substituteOriginalItemID">Substitute original item id</param>
/// <returns>Item id for the new sales order line</returns>
abstract protected ItemId setItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
{

}

/// <summary>
/// Update indicators for the new sales order line
/// </summary>
/// <param name = "_metSalesLine">Custom new sales order line</param>
abstract protected void updateIndicators(METSalesLine _metSalesLine)
{

}

/// <summary>
/// Set original item number for the new line
/// </summary>
/// <param name = "_substitutionType">Substitution type</param>
/// <param name = "_substituteOriginalItemID">Substitute original item id</param>
/// <returns>Substitute original item id</returns>
abstract protected METSubstituteOriginalItemID setOriginalItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
{

}

/// <summary>
/// Set substitute item number for the new line
/// </summary>
/// <returns>Substitute item ID</returns>
abstract protected METSubstituteItemID setSubstituteItemID()
{

}

/// <summary>
/// Set line indicator to 'N' for the new line to ensure the new substituted line is priced by PE.
/// </summary>
/// <returns>Line indicator</returns>
protected METLineIndicator setLineIndicator()
{
    return METLineIndicator::N;
}

/// <summary>
/// Indicate if the new sales order line must be cancelled or not
/// </summary>
/// <returns>boolean to cancel new sales line</returns>
abstract protected boolean cancelNewLine()
{

}

    /// <summary>
    /// Method to set the custom fields for the new sales order line
    /// </summary>
    /// <param name = "_metSalesLineNew">Custom new sales order line</param>
    /// <param name = "_metSalesLine">Custom existing sales order line</param>
    protected void setNewMetSalesLine(METSalesLine _metSalesLineNew, METSalesLine _metSalesLine)
    {
        // only for disabled
        _metSalesLineNew.SubstituteItemID = this.setSubstituteItemID();

        _metSalesLineNew.SubstitutionType = this.setSubstitutionType();
        _metSalesLineNew.SubstitutionCode = salesItemSubstitute.SubstitutionCode;
            
        // only for disabled
        // set new line reason code
        _metSalesLineNew.ReasonId = this.setReasonCode();

        // update indicators, remove or add S
        this.updateIndicators(_metSalesLineNew);

        // Leave this as the default value (“N”), to ensure the new substituted line is priced by PE.
        _metSalesLineNew.LineIndicator = this.setLineIndicator();

        // set original item for enabled only
        //this.setOriginalItemId(_metSalesLine, _metSalesLineNew);
        _metSalesLineNew.SubstituteOriginalItemID = this.setOriginalItemId(_metSalesLine.SubstitutionType, _metSalesLine.SubstituteOriginalItemID);

        // Updates subs recId
        _metSalesLineNew.SubstitutionSetupRefRecID = salesItemSubstitute.RecId;
    }

    /// <summary>
    /// Calculate substitute quantity based on unit conversions
    /// </summary>
    /// <param name = "_fromItemId">Item number</param>
    /// <param name = "_toItemId">Substitute item number</param>
    /// <param name = "_inventDimId">Inventory dimension id</param>
    /// <param name = "_fromUnit">From unit</param>
    /// <param name = "_toUnit">To unit</param>
    /// <param name = "_salesQty">Quantity to convert</param>
    /// <param name = "_salesSetup">Default sales order setting</param>
    /// <returns>New substitute quantity after conversion and using multiply and lowest qty if required</returns>
    protected SalesQty calculateSubstituteQty(ItemId               _fromItemId,
                                              ItemId               _toItemId,
                                              InventDimId          _inventDimId,
                                              UnitOfMeasureSymbol  _fromUnit,
                                              UnitOfMeasureSymbol  _toUnit,
                                              SalesQty             _salesQty,
                                              InventItemSalesSetup _salesSetup)
    {
        SalesQty ret;

        if (_fromUnit == _toUnit)
        {
            ret  = _salesQty;
        }
        else
        {
            if (EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, _fromUnit, _toUnit))
            {
                ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, _salesQty, _fromUnit, _toUnit);
            }
            else
            {
                if (EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_fromItemId, _inventDimId, _fromUnit, InventTableModule::find(_fromItemId, ModuleInventPurchSales::Invent).UnitId)
                &&  EcoResProductUnitConverter::canBeConvertedGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, InventTableModule::find(_toitemId, ModuleInventPurchSales::Invent).UnitId, _toUnit))
                {
                    ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_fromItemId, _inventDimId, _salesQty, _fromUnit, InventTableModule::find(_fromItemId, ModuleInventPurchSales::Invent).UnitId, NoYes::No, NoYes::No);
                    ret  = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_toItemId, _inventDimId, ret, InventTableModule::find(_toitemId, ModuleInventPurchSales::Invent).UnitId, _toUnit, NoYes::No, NoYes::No);
                    
                    ret = this.roundValue(ret, salesItemSubstitute.Rounding, _toUnit);

                    // check the AR parameter "Apply minimum & multiple quantities"
                    if (custParameters.METApplyMinAndMultipleQty)
                    {
                        // use InventItemSalesSetup.MultipleQty and InventItemSalesSetup.LowestQty (check if override default settings is ticked or not)
                        // Have a look at InventTable::calculateOrderQuantity()
                        // and convert qty again if required
                        ret = InventTable::calculateOrderQuantity(_salesSetup,
                                                                  _inventDimId,
                                                                  ret,
                                                                  _toUnit,
                                                                  false,
                                                                  true,
                                                                  true,
                                                                  true);
                    }

                }
                else
                {
                    ret = _salesQty;
                }
            }
        }

        return ret;
    }

    /// <summary>
    /// Applies rounding to a real value.
    /// </summary>
    /// <param name="_value">
    /// A real value.
    /// </param>
    /// <param name="_rounding">
    /// A rounding type.
    /// </param>
    /// <param name="_toUnit">
    /// Unit of measure.
    /// </param>
    /// <returns>
    /// A rounded real value.
    /// </returns>
    protected real roundValue(
        real                             _value,
        METSalesItemSubstitutionRounding _rounding,
        UnitOfMeasureSymbol              _toUnit)
    {
        UnitOfMeasureDecimalPrecision decimalPrecision = UnitOfMeasure::findBySymbol(_toUnit).DecimalPrecision;
        real    ret;
        int     sign    = 1;

        switch (_rounding)
        {
            case METSalesItemSubstitutionRounding::ToNearest   :
                ret = decRound(sign * _value, decimalPrecision);
                break;

            case METSalesItemSubstitutionRounding::Up        :
                ret = roundUpDec(sign * _value, decimalPrecision);
                break;

            case METSalesItemSubstitutionRounding::Down      :
                ret = roundDownDec(sign * _value, decimalPrecision);
                break;
        }

        return sign * ret;
    }

/// <summary>
/// Update sales order header processing status
/// </summary>
protected void updateSalesOrderProcessingStatus()
{
    ttsbegin;
    METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
    if (metSalesTable)
    {
        metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
        metSalesTable.update();
    }
    ttscommit;
}
